package com.mirutina.diaria;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.util.*;import java.io.*;
public class Scheduler {
 static JSONArray load(Context c)throws Exception {InputStream in=c.getAssets().open("schedule.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);in.close();return new JSONArray(out.toString("UTF-8"));}
 static void schedule(Context c){try{AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray week=load(c);Calendar now=Calendar.getInstance();for(int d=0;d<7;d++){JSONArray entries=week.getJSONArray(d);for(int k=0;k<entries.length();k++){JSONArray row=entries.getJSONArray(k);String time=row.getString(0),title=row.getString(2);if(title.equals("Dormir")||title.equals("Tiempo libre"))continue;String[] hm=time.split(":");Calendar at=Calendar.getInstance();at.set(Calendar.DAY_OF_WEEK,d==6?Calendar.SUNDAY:d+Calendar.MONDAY);at.set(Calendar.HOUR_OF_DAY,Integer.parseInt(hm[0]));at.set(Calendar.MINUTE,Integer.parseInt(hm[1]));at.set(Calendar.SECOND,0);at.set(Calendar.MILLISECOND,0);at.add(Calendar.MINUTE,-10);if(!at.after(now))at.add(Calendar.DAY_OF_YEAR,7);int id=d*100+k;Intent intent=new Intent(c,AlarmReceiver.class).putExtra("title",title).putExtra("id",id);PendingIntent pi=PendingIntent.getBroadcast(c,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at.getTimeInMillis(),pi);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at.getTimeInMillis(),pi);}}}catch(Exception ignored){}}
}
